-- 2026-10-31g: MP Background timelines for 25 most viewed MPs, batch 7 (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (399 entries, copied exactly from "background-batch7.json", which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 473, 4032, 4088, 4131, 4371, 4471, 4520, 4803, 4804, 4805, 4818, 5061, 5079, 5118, 5123, 5142, 5202, 5203, 5208, 5298, 5305, 5332, 5346, 5351, 5358,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-10-31g-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 96 existing timelines are unchanged (md5);
-- MPs with a timeline go from 96 to 121; each array equals the file exactly; 1719 entries in all afterwards.
-- Undo: 2026-10-31g-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (473, 4032, 4088, 4131, 4371, 4471, 4520, 4803, 4804, 4805, 4818, 5061, 5079, 5118, 5123, 5142, 5202, 5203, 5208, 5298, 5305, 5332, 5346, 5351, 5358)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (473, 4032, 4088, 4131, 4371, 4471, 4520, 4803, 4804, 4805, 4818, 5061, 5079, 5118, 5123, 5142, 5202, 5203, 5208, 5298, 5305, 5332, 5346, 5351, 5358) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 96 THEN RAISE EXCEPTION 'expected 96 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
